import{_ as e,o as a,c as i,a2 as n}from"./chunks/framework.mRCPFc5l.js";const E=JSON.parse('{"title":"Fsystem and Fspec Files","description":"","frontmatter":{"title":"Fsystem and Fspec Files"},"headers":[],"relativePath":"language-reference/fsystem_fspec.md","filePath":"language-reference/fsystem_fspec.md"}'),t={name:"language-reference/fsystem_fspec.md"};function l(o,s,p,c,r,h){return a(),i("div",null,[...s[0]||(s[0]=[n(`<h1 id="fsystem-and-fspec-files" tabindex="-1">Fsystem and Fspec Files <a class="header-anchor" href="#fsystem-and-fspec-files" aria-label="Permalink to &quot;Fsystem and Fspec Files&quot;">​</a></h1><p>Fault has two different types of files the compiler knows how to read <code>.fsystem</code> files which define the model&#39;s state chart and <code>.fspec</code> files which define model specifications. You can define models to use either a single <code>.fsystem</code> or a single <code>.fspec</code> file, or use an <code>.fsystem</code> file to import multiple <code>.fspec</code> files for more complex systems.</p><h2 id="single-level-imports" tabindex="-1">Single Level Imports <a class="header-anchor" href="#single-level-imports" aria-label="Permalink to &quot;Single Level Imports&quot;">​</a></h2><p>Only <code>.fsystem</code> files can import other files. Fault only allows a single level of imports. A model state chart can import specifications. State charts cannot import other state charts. Specifications cannot import state charts or other specifications. This allows models to be broken up into reusable parts, but doesn&#39;t allow circular imports or long dependency chains. In general I&#39;m cynical about the benefits of complex inheritance patterns and over generalized abstractions from OOP. I think such things make code look pretty at the expense of understanding the behavior of that code, which is of greater importance.</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">classDiagram</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Fsystem &lt;.. cache</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Fsystem &lt;.. orchestrator</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Fsystem : record (cache)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Fsystem : manager (orchestrator)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Fsystem: replCache</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Fsystem: containerMng</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    class cache{</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      machine</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      lookup()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      release()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      store()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      expire()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    class orchestrator{</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      p</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      add()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      remove()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      boot()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span></code></pre></div><h2 id="layout-of-a-fsystem-file" tabindex="-1">Layout of a Fsystem File <a class="header-anchor" href="#layout-of-a-fsystem-file" aria-label="Permalink to &quot;Layout of a Fsystem File&quot;">​</a></h2><p><code>.fsystem</code> files have a set of required elements and the set of optional elements.</p><p>|:-------------|:------------------| | <strong>Required</strong> | System Declaration, Components | | <strong>Optional</strong> | Imports, Globals, Assertions, Run Block |</p><p>A <code>.fsystem</code> file is the state chart of the entire system being modelled. It&#39;s the high level view of system behavior. Assertions particular to stock/flow behavior should be in the <code>.fspec</code> file where those behaviors are defined if possible so that everything in the <code>.fsystem</code> focuses on the state chart.</p><p>The compiler expects a system declaration first, followed by any imports, followed by a body containing globals, constants, components, and assertions in any order. The run block always comes last.</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    sysClause[System Declaration] -..- imports[Imports]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    imports ===  globals[Initialize Globals]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    sysClause  -..-  component[Components]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    sysClause -..- assert[Assertions]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    sysClause -..- runBlock[Run Block]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    class imports merOpNode</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    class assert merOpNode</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    class runBlock merOpNode</span></span></code></pre></div><h2 id="fspec-files" tabindex="-1">Fspec Files <a class="header-anchor" href="#fspec-files" aria-label="Permalink to &quot;Fspec Files&quot;">​</a></h2><p><code>.fspec</code> files have a similar structure to the <code>.fsystem</code> file but a different set of structures can be declared.</p><p>|:-------------|:------------------| | <strong>Required</strong> | Spec Declaration, Stocks/Flows | | <strong>Optional</strong> | Constants, Assertions, Run Block |</p><p>A <code>.fspec</code> file defines one complete interaction that determines the transition of the state machine from one state to another. Stocks/Flows can be defined in a <code>.fspec</code> file but not components. Likewise components can be defined in <code>.fsystem</code> but Stock/Flows must be imported.</p><p>Single file models in Fault--therefore--are either all state machine, or a specification of a single process.</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    specClause[Spec Declaration] -..- constants[Model Constants]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    specClause  -..-  stocks[Stocks]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    specClause  -..-  flows[Flows]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    specClause -..- assert[Assertions]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    specClause -..- runBlock[Run Block]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    class constants merOpNode</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    class assert merOpNode</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    class runBlock merOpNode</span></span></code></pre></div>`,17)])])}const k=e(t,[["render",l]]);export{E as __pageData,k as default};
